import { useAccount } from '../context/AccountContext';
import { useAuth } from '../context/AuthContext';
import { PERMISSIONS, APP_VERSION, APP_VERSION_NOTE } from '../utils/config';

const NAV_MAIN = [
  { id:'dashboard',  label:'首頁總覽',  short:'首頁', icon:'◈', perm:null },
  { id:'upload',     label:'報表上傳',  short:'上傳', icon:'↑', perm:'UPLOAD' },
  { id:'sales',      label:'銷貨總表',  short:'銷貨', icon:'▦', perm:null },
  { id:'pnl',        label:'損益表',    short:'損益', icon:'$', perm:'FINANCE' },
];
const NAV_OPS = [
  { id:'order',      label:'手動開單',  short:'開單', icon:'◇', perm:'ORDER' },
  { id:'inventory',  label:'庫存管理',  short:'庫存', icon:'▣', perm:'INVENTORY' },
  { id:'crm',        label:'客戶管理',  short:'客戶', icon:'◉', perm:'ORDER' },
  { id:'query',      label:'銷貨/入庫查詢', short:'查詢', icon:'⊙', perm:'VIEW_ALL' },
];
const NAV_SYS = [
  { id:'accounts',   label:'帳號管理',  short:'帳號', icon:'🔐', perm:'MASTER' },
  { id:'settings',   label:'系統設定',  short:'設定', icon:'⊞', perm:'SETTINGS' },
  { id:'help',       label:'操作手冊',  short:'說明', icon:'?',  perm:null },
];

export default function Sidebar({ page, setPage }) {
  const { currentAccount, can } = useAccount();
  const { logout } = useAuth();
  const initials = currentAccount?.name
    ? currentAccount.name.slice(0,2).toUpperCase()
    : '?';

  const NavItem = ({ item }) => {
    const allowed = !item.perm || can(item.perm);
    if (!allowed) return null;
    return (
      <div
        className={`nav-item${page===item.id?' active':''}`}
        onClick={() => setPage(item.id)}
        style={{ opacity: allowed ? 1 : 0.3 }}>
        <span style={{ width:14, textAlign:'center', fontSize:14 }}>{item.icon}</span>
        {item.label}
      </div>
    );
  };

  return (
    <aside className="sidebar">
      <div className="sidebar-logo">
        <h1>損益彙整系統</h1>
        <p title={APP_VERSION_NOTE} style={{ cursor:'help' }}>版本 {APP_VERSION}</p>
      </div>

      <div className="sidebar-section">
        <div className="sidebar-section-label">主選單</div>
        {NAV_MAIN.map(item => <NavItem key={item.id} item={item}/>)}
      </div>

      <div className="sidebar-section">
        <div className="sidebar-section-label">進階功能</div>
        {NAV_OPS.map(item => <NavItem key={item.id} item={item}/>)}
      </div>

      <div className="sidebar-section">
        <div className="sidebar-section-label">系統</div>
        {NAV_SYS.map(item => <NavItem key={item.id} item={item}/>)}
      </div>

      <div className="sidebar-footer">
        <div className="user-avatar">{initials}</div>
        <div style={{ flex:1, minWidth:0 }}>
          <div className="user-name">{currentAccount?.name || '使用者'}</div>
          <div className="user-email" style={{ fontSize:14 }}>
            {currentAccount?.perms?.includes('MASTER') ? '🔐 Master' : '一般成員'}
          </div>
        </div>
        <div style={{ display:'flex', gap:12 }}>
          <span style={{ fontSize:17, color:'var(--muted)', cursor:'pointer' }}
            onClick={() => setPage('accounts')} title="帳號管理">⚙</span>
          <span style={{ fontSize:17, color:'var(--muted)', cursor:'pointer' }}
            onClick={logout} title="登出">⏻</span>
        </div>
      </div>
    </aside>
  );
}